pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    function setUp() public { c = new LiquidityPool(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(bytes32 what, address data) public {
        bool ok;
        try c.file(what, data) { ok = true; } catch { ok = false; }
        assertTrue(ok ? (what == "investmentManager") == (address(c.investmentManager()) == data) : true);
    }
